import{_ as a,a as r,b as i,c as e,d as o,e as s,f as n,g as d,h,i as l,j as c}from"./chunks/chat-import-07.B7k0d_Ex.js";import{_ as g,o as p,c as f,a3 as u}from"./chunks/framework.D1iekJsc.js";const A=JSON.parse('{"title":"聊天存檔","description":"MiniTavern 單聊存檔：導出 ZIP、從列表或文件導入；合併到已有聊天或作為新聊天。","frontmatter":{"title":"聊天存檔","description":"MiniTavern 單聊存檔：導出 ZIP、從列表或文件導入；合併到已有聊天或作為新聊天。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"聊天存檔 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 單聊存檔：導出 ZIP、從列表或文件導入；合併到已有聊天或作為新聊天。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/manual/chat-archive"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/manual/chat-archive"}]]},"headers":[],"relativePath":"zh-TW/manual/chat-archive.md","filePath":"zh-TW/manual/chat-archive.md","lastUpdated":1787816217000}'),m={name:"zh-TW/manual/chat-archive.md"};function b(_,t,T,v,P,I){return p(),f("div",null,[...t[0]||(t[0]=[u('<h1 id="聊天存檔" tabindex="-1">聊天存檔 <a class="header-anchor" href="#聊天存檔" aria-label="Permalink to &quot;聊天存檔&quot;">​</a></h1><p>聊天存檔是<strong>單個會話</strong>的 ZIP 包，用來備份長線劇情、換機帶走或分享給他人。與 <a href="./backup">全量備份</a>（全量 ZIP）不同，請勿混用恢復入口。</p><p>路徑：<strong>設置 → 數據管理 → 聊天存檔</strong>（管理已保存的存檔文件）。</p><h2 id="導出-創建存檔" tabindex="-1">導出（創建存檔） <a class="header-anchor" href="#導出-創建存檔" aria-label="Permalink to &quot;導出（創建存檔）&quot;">​</a></h2><p>導出會打包當前會話的消息、會話配置與相關本地資源，完成後寫入 App 內「聊天存檔」列表，也可在進度結束後分享 ZIP。</p><h3 id="會話列表-·-三點菜單" tabindex="-1">會話列表 · 三點菜單 <a class="header-anchor" href="#會話列表-·-三點菜單" aria-label="Permalink to &quot;會話列表 · 三點菜單&quot;">​</a></h3><p>在 <strong>聊天</strong> Tab 的會話卡片上點 <strong>⋯</strong>（操作菜單）→ <strong>存檔</strong>。</p><div class="shot-flow"><figure class="shot-step"><img src="'+a+'" alt="三點菜單"><figcaption>1 · 點擊操作</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="存檔"><figcaption>2 · 選擇存檔</figcaption></figure></div><h3 id="聊天設置-·-底部按鈕" tabindex="-1">聊天設置 · 底部按鈕 <a class="header-anchor" href="#聊天設置-·-底部按鈕" aria-label="Permalink to &quot;聊天設置 · 底部按鈕&quot;">​</a></h3><p>對話頁 → <strong>聊天設置</strong> → 滾動到底部，點 <strong>存檔</strong>（與「重新開始」並排）。</p><div class="shot-flow"><figure class="shot-step"><img src="'+i+'" alt="聊天設置底部"><figcaption>1 · 聊天頁點擊設置</figcaption></figure><figure class="shot-step"><img src="'+e+'" alt="存檔按鈕"><figcaption>2 · 選擇存檔</figcaption></figure></div><h3 id="聊天存檔列表-·-創建存檔" tabindex="-1">聊天存檔列表 · 創建存檔 <a class="header-anchor" href="#聊天存檔列表-·-創建存檔" aria-label="Permalink to &quot;聊天存檔列表 · 創建存檔&quot;">​</a></h3><p><strong>設置 → 數據管理 → 聊天存檔</strong> → 右上角 <strong>+</strong> → <strong>創建存檔</strong> → 選擇要導出的會話（流程與上相同）。</p><h2 id="導入" tabindex="-1">導入 <a class="header-anchor" href="#導入" aria-label="Permalink to &quot;導入&quot;">​</a></h2><p>導入前會校驗文件是否為聊天存檔；若選成全量備份或無效文件，進度彈窗會提示錯誤並退出。</p><p>若本機已存在<strong>同一聊天</strong>（相同會話 ID），會彈出方式選擇：</p><p><img src="'+o+'" alt="合併或作為新聊天"></p><table tabindex="0"><thead><tr><th>方式</th><th>說明</th></tr></thead><tbody><tr><td><strong>合併到已有聊天</strong></td><td>將存檔內容併入已存在的會話，較新數據覆蓋較舊</td></tr><tr><td><strong>作為新聊天導入</strong></td><td>保留當前聊天，存檔另開一條新會話</td></tr></tbody></table><h3 id="聊天-tab-·-導航欄右側" tabindex="-1">聊天 Tab · 導航欄右側 <a class="header-anchor" href="#聊天-tab-·-導航欄右側" aria-label="Permalink to &quot;聊天 Tab · 導航欄右側&quot;">​</a></h3><p><strong>聊天</strong> Tab 右上角 <strong>+</strong>：</p><table tabindex="0"><thead><tr><th>菜單項</th><th>行為</th></tr></thead><tbody><tr><td><strong>從存檔導入</strong></td><td>從 App 內已保存的聊天存檔列表中選一條導入</td></tr><tr><td><strong>從文件導入</strong></td><td>用系統文件選擇器選外部 ZIP，校驗後進入上述導入流程</td></tr></tbody></table><p>列表內暫無存檔時選「從存檔導入」會提示先去導出。</p><div class="shot-flow"><figure class="shot-step"><img src="'+s+'" alt="聊天 Tab 加號"><figcaption>1 · 聊天 Tab · +</figcaption></figure><figure class="shot-step"><img src="'+n+'" alt="從存檔或文件導入"><figcaption>2 · 從存檔 / 從文件導入</figcaption></figure></div><h3 id="聊天存檔列表" tabindex="-1">聊天存檔列表 <a class="header-anchor" href="#聊天存檔列表" aria-label="Permalink to &quot;聊天存檔列表&quot;">​</a></h3><p><strong>設置 → 數據管理 → 聊天存檔</strong>：</p><table tabindex="0"><thead><tr><th>入口</th><th>行為</th></tr></thead><tbody><tr><td>右上角 <strong>+</strong> → <strong>從文件導入</strong></td><td>與聊天 Tab「從文件導入」相同</td></tr><tr><td>某條存檔右側菜單 → <strong>導入</strong></td><td>直接導入該條已保存的存檔</td></tr></tbody></table><div class="shot-flow"><figure class="shot-step"><img src="'+d+'" alt="聊天存檔列表"><figcaption>1 · 設置頁選擇存檔與備份</figcaption></figure><figure class="shot-step"><img src="'+h+'" alt="列表導入入口"><figcaption>2 · 選擇聊天存檔</figcaption></figure><figure class="shot-step"><img src="'+l+'" alt="導入存檔"><figcaption>3 · 點擊操作</figcaption></figure><figure class="shot-step"><img src="'+c+'" alt="存檔列表操作"><figcaption>4 · 導入/分享 / 管理存檔</figcaption></figure></div><p>列表內還可 <strong>分享</strong>、重命名、置頂、刪除存檔文件（刪除不可恢復）。</p><h2 id="與全量備份的區別" tabindex="-1">與全量備份的區別 <a class="header-anchor" href="#與全量備份的區別" aria-label="Permalink to &quot;與全量備份的區別&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>聊天存檔</th><th>全量備份</th></tr></thead><tbody><tr><td>範圍</td><td>單個會話</td><td>角色、全部聊天、世界書等</td></tr><tr><td>格式</td><td>單聊 ZIP</td><td>全量 ZIP</td></tr><tr><td>恢復入口</td><td>聊天 Tab / 聊天存檔列表</td><td>設置 → 數據管理 → 備份恢復</td></tr></tbody></table><p>全量備份說明見 <a href="./backup">備份與存檔</a>。</p><h2 id="出錯時" tabindex="-1">出錯時 <a class="header-anchor" href="#出錯時" aria-label="Permalink to &quot;出錯時&quot;">​</a></h2><p>導入/導出失敗可查看進度彈窗或 Toast 提示；常見原因包括文件類型錯誤、磁盤空間不足。氣泡級錯誤對照 <a href="./errors">錯誤代碼排錯</a>。</p>',33)])])}const x=g(m,[["render",b]]);export{A as __pageData,x as default};
